  1	package create
  2	
  3	import (
  4		"errors"
  5		"fmt"
  6		"net/http"
  7	
  8		"github.com/MakeNowJust/heredoc"
  9		"github.com/cli/cli/api"
 10		"github.com/cli/cli/internal/config"
 11		"github.com/cli/cli/internal/ghrepo"
 12		"github.com/cli/cli/pkg/cmd/pr/shared"
 13		prShared "github.com/cli/cli/pkg/cmd/pr/shared"
 14		"github.com/cli/cli/pkg/cmdutil"
 15		"github.com/cli/cli/pkg/iostreams"
 16		"github.com/cli/cli/utils"
 17		"github.com/spf13/cobra"
 18	)
 19	
 20	type CreateOptions struct {
 21		HttpClient func() (*http.Client, error)
 22		Config     func() (config.Config, error)
 23		IO         *iostreams.IOStreams
 24		BaseRepo   func() (ghrepo.Interface, error)
 25	
 26		RootDirOverride string
 27	
 28		RepoOverride string
 29		WebMode      bool
 30		RecoverFile  string
 31	
 32		Title       string
 33		Body        string
 34		Interactive bool
 35	
 36		Assignees []string
 37		Labels    []string
 38		Projects  []string
 39		Milestone string
 40	}
 41	
 42	func NewCmdCreate(f *cmdutil.Factory, runF func(*CreateOptions) error) *cobra.Command {
 43		opts := &CreateOptions{
 44			IO:         f.IOStreams,
 45			HttpClient: f.HttpClient,
 46			Config:     f.Config,
 47		}
 48	
 49		cmd := &cobra.Command{
 50			Use:   "create",
 51			Short: "Create a new issue",
 52			Example: heredoc.Doc(`
 53				$ gh issue create --title "I found a bug" --body "Nothing works"
 54				$ gh issue create --label "bug,help wanted"
 55				$ gh issue create --label bug --label "help wanted"
 56				$ gh issue create --assignee monalisa,hubot
 57				$ gh issue create --assignee @me
 58				$ gh issue create --project "Roadmap"
 59			`),
 60			Args: cmdutil.NoArgsQuoteReminder,
 61			RunE: func(cmd *cobra.Command, args []string) error {
 62				// support `-R, --repo` override
 63				opts.BaseRepo = f.BaseRepo
 64	
 65				titleProvided := cmd.Flags().Changed("title")
 66				bodyProvided := cmd.Flags().Changed("body")
 67				opts.RepoOverride, _ = cmd.Flags().GetString("repo")
 68	
 69				if !opts.IO.CanPrompt() && opts.RecoverFile != "" {
 70					return &cmdutil.FlagError{Err: errors.New("--recover only supported when running interactively")}
 71				}
 72	
 73				opts.Interactive = !(titleProvided && bodyProvided)
 74	
 75				if opts.Interactive && !opts.IO.CanPrompt() {
 76					return &cmdutil.FlagError{Err: errors.New("must provide --title and --body when not running interactively")}
 77				}
 78	
 79				if runF != nil {
 80					return runF(opts)
 81				}
 82				return createRun(opts)
 83			},
 84		}
 85	
 86		cmd.Flags().StringVarP(&opts.Title, "title", "t", "", "Supply a title. Will prompt for one otherwise.")
 87		cmd.Flags().StringVarP(&opts.Body, "body", "b", "", "Supply a body. Will prompt for one otherwise.")
 88		cmd.Flags().BoolVarP(&opts.WebMode, "web", "w", false, "Open the browser to create an issue")
 89		cmd.Flags().StringSliceVarP(&opts.Assignees, "assignee", "a", nil, "Assign people by their `login`. Use \"@me\" to self-assign.")
 90		cmd.Flags().StringSliceVarP(&opts.Labels, "label", "l", nil, "Add labels by `name`")
 91		cmd.Flags().StringSliceVarP(&opts.Projects, "project", "p", nil, "Add the issue to projects by `name`")
 92		cmd.Flags().StringVarP(&opts.Milestone, "milestone", "m", "", "Add the issue to a milestone by `name`")
 93		cmd.Flags().StringVar(&opts.RecoverFile, "recover", "", "Recover input from a failed run of create")
 94	
 95		return cmd
 96	}
 97	
 98	func createRun(opts *CreateOptions) (err error) {
 99		httpClient, err := opts.HttpClient()
100		if err != nil {
101			return
102		}
103		apiClient := api.NewClientFromHTTP(httpClient)
104	
105		baseRepo, err := opts.BaseRepo()
106		if err != nil {
107			return
108		}
109	
110		templateFiles, legacyTemplate := prShared.FindTemplates(opts.RootDirOverride, "ISSUE_TEMPLATE")
111	
112		isTerminal := opts.IO.IsStdoutTTY()
113	
114		var milestones []string
115		if opts.Milestone != "" {
116			milestones = []string{opts.Milestone}
117		}
118	
119		meReplacer := shared.NewMeReplacer(apiClient, baseRepo.RepoHost())
120		assignees, err := meReplacer.ReplaceSlice(opts.Assignees)
121		if err != nil {
122			return err
123		}
124	
125		tb := prShared.IssueMetadataState{
126			Type:       prShared.IssueMetadata,
127			Assignees:  assignees,
128			Labels:     opts.Labels,
129			Projects:   opts.Projects,
130			Milestones: milestones,
131			Title:      opts.Title,
132			Body:       opts.Body,
133		}
134	
135		if opts.RecoverFile != "" {
136			err = prShared.FillFromJSON(opts.IO, opts.RecoverFile, &tb)
137			if err != nil {
138				err = fmt.Errorf("failed to recover input: %w", err)
139				return
140			}
141		}
142	
143		if opts.WebMode {
144			openURL := ghrepo.GenerateRepoURL(baseRepo, "issues/new")
145			if opts.Title != "" || opts.Body != "" || len(opts.Assignees) > 0 {
146				openURL, err = prShared.WithPrAndIssueQueryParams(openURL, tb)
147				if err != nil {
148					return
149				}
150			} else if len(templateFiles) > 1 {
151				openURL += "/choose"
152			}
153			if isTerminal {
154				fmt.Fprintf(opts.IO.ErrOut, "Opening %s in your browser.\n", utils.DisplayURL(openURL))
155			}
156			return utils.OpenInBrowser(openURL)
157		}
158	
159		if isTerminal {
160			fmt.Fprintf(opts.IO.ErrOut, "\nCreating issue in %s\n\n", ghrepo.FullName(baseRepo))
161		}
162	
163		repo, err := api.GitHubRepo(apiClient, baseRepo)
164		if err != nil {
165			return
166		}
167		if !repo.HasIssuesEnabled {
168			err = fmt.Errorf("the '%s' repository has disabled issues", ghrepo.FullName(baseRepo))
169			return
170		}
171	
172		action := prShared.SubmitAction
173	
174		if opts.Interactive {
175			var editorCommand string
176			editorCommand, err = cmdutil.DetermineEditor(opts.Config)
177			if err != nil {
178				return
179			}
180	
181			defer prShared.PreserveInput(opts.IO, &tb, &err)()
182	
183			if opts.Title == "" {
184				err = prShared.TitleSurvey(&tb)
185				if err != nil {
186					return
187				}
188			}
189	
190			if opts.Body == "" {
191				templateContent := ""
192	
193				if opts.RecoverFile == "" {
194					templateContent, err = prShared.TemplateSurvey(templateFiles, legacyTemplate, tb)
195					if err != nil {
196						return
197					}
198				}
199	
200				err = prShared.BodySurvey(&tb, templateContent, editorCommand)
201				if err != nil {
202					return
203				}
204	
205				if tb.Body == "" {
206					tb.Body = templateContent
207				}
208			}
209	
210			action, err = prShared.ConfirmSubmission(!tb.HasMetadata(), repo.ViewerCanTriage())
211			if err != nil {
212				err = fmt.Errorf("unable to confirm: %w", err)
213				return
214			}
215	
216			if action == prShared.MetadataAction {
217				fetcher := &prShared.MetadataFetcher{
218					IO:        opts.IO,
219					APIClient: apiClient,
220					Repo:      baseRepo,
221					State:     &tb,
222				}
223				err = prShared.MetadataSurvey(opts.IO, baseRepo, fetcher, &tb)
224				if err != nil {
225					return
226				}
227	
228				action, err = prShared.ConfirmSubmission(!tb.HasMetadata(), false)
229				if err != nil {
230					return
231				}
232			}
233	
234			if action == prShared.CancelAction {
235				fmt.Fprintln(opts.IO.ErrOut, "Discarding.")
236				return
237			}
238		} else {
239			if tb.Title == "" {
240				err = fmt.Errorf("title can't be blank")
241				return
242			}
243		}
244	
245		if action == prShared.PreviewAction {
246			openURL := ghrepo.GenerateRepoURL(baseRepo, "issues/new")
247			openURL, err = prShared.WithPrAndIssueQueryParams(openURL, tb)
248			if err != nil {
249				return
250			}
251			if isTerminal {
252				fmt.Fprintf(opts.IO.ErrOut, "Opening %s in your browser.\n", utils.DisplayURL(openURL))
253			}
254			return utils.OpenInBrowser(openURL)
255		} else if action == prShared.SubmitAction {
256			params := map[string]interface{}{
257				"title": tb.Title,
258				"body":  tb.Body,
259			}
260	
261			err = prShared.AddMetadataToIssueParams(apiClient, baseRepo, params, &tb)
262			if err != nil {
263				return
264			}
265	
266			var newIssue *api.Issue
267			newIssue, err = api.IssueCreate(apiClient, repo, params)
268			if err != nil {
269				return
270			}
271	
272			fmt.Fprintln(opts.IO.Out, newIssue.URL)
273		} else {
274			panic("Unreachable state")
275		}
276	
277		return
278	}

