  1	package shared
  2	
  3	import (
  4		"fmt"
  5		"net/url"
  6		"strings"
  7	
  8		"github.com/cli/cli/api"
  9		"github.com/cli/cli/internal/ghrepo"
 10	)
 11	
 12	func WithPrAndIssueQueryParams(baseURL string, state IssueMetadataState) (string, error) {
 13		u, err := url.Parse(baseURL)
 14		if err != nil {
 15			return "", err
 16		}
 17		q := u.Query()
 18		if state.Title != "" {
 19			q.Set("title", state.Title)
 20		}
 21		if state.Body != "" {
 22			q.Set("body", state.Body)
 23		}
 24		if len(state.Assignees) > 0 {
 25			q.Set("assignees", strings.Join(state.Assignees, ","))
 26		}
 27		if len(state.Labels) > 0 {
 28			q.Set("labels", strings.Join(state.Labels, ","))
 29		}
 30		if len(state.Projects) > 0 {
 31			q.Set("projects", strings.Join(state.Projects, ","))
 32		}
 33		if len(state.Milestones) > 0 {
 34			q.Set("milestone", state.Milestones[0])
 35		}
 36		u.RawQuery = q.Encode()
 37		return u.String(), nil
 38	}
 39	
 40	// Ensure that tb.MetadataResult object exists and contains enough pre-fetched API data to be able
 41	// to resolve all object listed in tb to GraphQL IDs.
 42	func fillMetadata(client *api.Client, baseRepo ghrepo.Interface, tb *IssueMetadataState) error {
 43		resolveInput := api.RepoResolveInput{}
 44	
 45		if len(tb.Assignees) > 0 && (tb.MetadataResult == nil || len(tb.MetadataResult.AssignableUsers) == 0) {
 46			resolveInput.Assignees = tb.Assignees
 47		}
 48	
 49		if len(tb.Reviewers) > 0 && (tb.MetadataResult == nil || len(tb.MetadataResult.AssignableUsers) == 0) {
 50			resolveInput.Reviewers = tb.Reviewers
 51		}
 52	
 53		if len(tb.Labels) > 0 && (tb.MetadataResult == nil || len(tb.MetadataResult.Labels) == 0) {
 54			resolveInput.Labels = tb.Labels
 55		}
 56	
 57		if len(tb.Projects) > 0 && (tb.MetadataResult == nil || len(tb.MetadataResult.Projects) == 0) {
 58			resolveInput.Projects = tb.Projects
 59		}
 60	
 61		if len(tb.Milestones) > 0 && (tb.MetadataResult == nil || len(tb.MetadataResult.Milestones) == 0) {
 62			resolveInput.Milestones = tb.Milestones
 63		}
 64	
 65		metadataResult, err := api.RepoResolveMetadataIDs(client, baseRepo, resolveInput)
 66		if err != nil {
 67			return err
 68		}
 69	
 70		if tb.MetadataResult == nil {
 71			tb.MetadataResult = metadataResult
 72		} else {
 73			tb.MetadataResult.Merge(metadataResult)
 74		}
 75	
 76		return nil
 77	}
 78	
 79	func AddMetadataToIssueParams(client *api.Client, baseRepo ghrepo.Interface, params map[string]interface{}, tb *IssueMetadataState) error {
 80		if !tb.HasMetadata() {
 81			return nil
 82		}
 83	
 84		if err := fillMetadata(client, baseRepo, tb); err != nil {
 85			return err
 86		}
 87	
 88		assigneeIDs, err := tb.MetadataResult.MembersToIDs(tb.Assignees)
 89		if err != nil {
 90			return fmt.Errorf("could not assign user: %w", err)
 91		}
 92		params["assigneeIds"] = assigneeIDs
 93	
 94		labelIDs, err := tb.MetadataResult.LabelsToIDs(tb.Labels)
 95		if err != nil {
 96			return fmt.Errorf("could not add label: %w", err)
 97		}
 98		params["labelIds"] = labelIDs
 99	
100		projectIDs, err := tb.MetadataResult.ProjectsToIDs(tb.Projects)
101		if err != nil {
102			return fmt.Errorf("could not add to project: %w", err)
103		}
104		params["projectIds"] = projectIDs
105	
106		if len(tb.Milestones) > 0 {
107			milestoneID, err := tb.MetadataResult.MilestoneToID(tb.Milestones[0])
108			if err != nil {
